<?php
declare(strict_types=1);

/** Private activity summaries. No clinical data, GPS, public publishing or AI access. */
final class FitnessException extends RuntimeException {}
function fitness_sources(): array {return ['google_health'=>'Google Health','strava'=>'Strava','health_connect'=>'Android Health Connect','samsung_health'=>'Samsung Health export','google_fit'=>'Google Fit export'];}
function fitness_provider(string $source): void {if(!isset(fitness_sources()[$source]))throw new FitnessException('Choose an activity source.');}
function fitness_key(int $uid,string $kind,string $source=''): string {if($uid<1||!in_array($kind,['grant','data','stage','targets'],true))throw new FitnessException('Invalid private activity record.');if($source!=='')fitness_provider($source);return 'activity.'.$uid.'.'.$kind.($source!==''?'.'.$source:'');}
function fitness_text(mixed $v,int $max=200): string {if(!is_string($v)||mb_strlen($v)>$max||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f\x7f]/',$v))throw new FitnessException('Review the activity text fields.');return trim($v);}
function fitness_number(mixed $v,float $max,bool $whole=false): ?float {if($v===null||$v==='')return null;if(!is_int($v)&&!is_float($v)&&!(is_string($v)&&preg_match('/^(?:0|[1-9][0-9]*)(?:\.[0-9]+)?$/D',$v)))throw new FitnessException('Activity metrics must be nonnegative numbers; leave unavailable values blank.');$n=(float)$v;if(!is_finite($n)||$n<0||$n>$max||($whole&&floor($n)!==$n))throw new FitnessException('An activity metric is outside the supported range.');return $n;}
function fitness_time(mixed $v): int {if(!is_string($v)||!preg_match('/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.[0-9]{1,9})?(?:Z|[+-]\d\d:\d\d)$/D',$v))throw new FitnessException('Use full activity timestamps with UTC or an explicit timezone offset.');try{$d=new DateTimeImmutable($v);}catch(Throwable){throw new FitnessException('Invalid activity timestamp.');}$errors=DateTimeImmutable::getLastErrors();if(is_array($errors)&&($errors['warning_count']||$errors['error_count']))throw new FitnessException('Invalid activity date.');$t=$d->getTimestamp();if($t<946684800||$t>time()+86400)throw new FitnessException('Activity dates must be between 2000 and tomorrow.');return $t;}
function fitness_row(array $r,string $source): array {
 fitness_provider($source);$id=fitness_text($r['id']??'',240);if($id==='')throw new FitnessException('Every activity needs a stable source identifier.');$start=fitness_time($r['start_time']??null);$end=fitness_time($r['end_time']??null);if($end<=$start||$end-$start>604800)throw new FitnessException('Activity end must follow its start and span at most seven days.');
 $duration=fitness_number($r['duration_seconds']??null,604800);if($duration!==null&&$duration>$end-$start+1)throw new FitnessException('Active duration cannot exceed elapsed duration.');
 return ['id'=>$id,'source'=>$source,'origin'=>fitness_text($r['origin']??$source,200),'title'=>fitness_text($r['title']??'Activity',200),'type'=>fitness_text($r['type']??'Other',80),'start'=>$start,'end'=>$end,'seconds'=>$duration,'elapsed'=>$end-$start,'distance_m'=>fitness_number($r['distance_m']??null,2000000),'steps'=>fitness_number($r['steps']??null,1000000,true),'calories_kcal'=>fitness_number($r['calories_kcal']??null,100000)];
}
function fitness_unique(array $rows): array {$out=[];foreach($rows as$r){$key=$r['source'].'|'.$r['origin'].'|'.$r['id'];if(isset($out[$key])&&$out[$key]!==$r)throw new FitnessException('Conflicting versions of the same source activity. Export it again.');$out[$key]=$r;}return array_values($out);}
function fitness_csv(string $raw,string $source): array {
 if(!in_array($source,['health_connect','samsung_health','google_fit'],true))throw new FitnessException('Use the provider connection for cloud activities.');if(strlen($raw)>2000000||!mb_check_encoding($raw,'UTF-8')||str_contains($raw,"\0"))throw new FitnessException('Choose a UTF-8 activity CSV up to 2 MB.');$raw=preg_replace('/^\xEF\xBB\xBF/','',$raw);$f=fopen('php://temp','w+');fwrite($f,$raw);rewind($f);
 try{$header=fgetcsv($f,0,',','"','');$allowed=['id','title','type','start_time','end_time','duration_seconds','distance_m','steps','calories_kcal','origin'];if(!is_array($header)||count($header)!==count(array_unique($header))||array_diff(['id','start_time','end_time'],$header)||array_diff($header,$allowed))throw new FitnessException('Use the activity template or companion export. Unmapped vendor exports need conversion; GPS and clinical fields are not imported.');$rows=[];while(($cells=fgetcsv($f,0,',','"',''))!==false){if($cells===[null])continue;if(count($rows)>=2000||count($cells)!==count($header))throw new FitnessException('The CSV is incomplete or exceeds 2,000 activities.');$rows[]=fitness_row(array_combine($header,$cells),$source);}if(!$rows)throw new FitnessException('The file contains no activities.');return fitness_unique($rows);}finally{fclose($f);}
}
function fitness_range(array $input): array {
 $zone=comm_zone($input['timezone']??'Africa/Nairobi');$period=$input['period']??'month';if(!in_array($period,['week','month','year','custom'],true))throw new FitnessException('Choose weekly, monthly, annual or custom reporting.');$today=(new DateTimeImmutable('now',$zone))->format('Y-m-d');$anchor=comm_date($input['anchor']??$today);if($anchor>(new DateTimeImmutable('now',$zone))->modify('+1 year')->format('Y-m-d')||$anchor<'2000-01-01')throw new FitnessException('Choose a reporting or target anchor between 2000 and one year ahead.');$day=new DateTimeImmutable($anchor.'T00:00:00',$zone);
 if($period==='week'){$first=$day->modify('-'.((int)$day->format('N')-1).' days');$last=$first->modify('+7 days');}
 elseif($period==='month'){$first=$day->modify('first day of this month');$last=$first->modify('+1 month');}
 elseif($period==='year'){$first=$day->setDate((int)$day->format('Y'),1,1);$last=$first->modify('+1 year');}
 else{$from=comm_date($input['from']??$today);$to=comm_date($input['to']??$today);if($to>$today)throw new FitnessException('Custom reports must end no later than today.');$first=new DateTimeImmutable($from.'T00:00:00',$zone);$last=(new DateTimeImmutable($to.'T00:00:00',$zone))->modify('+1 day');}
 $start=$first->getTimestamp();$end=$last->getTimestamp();if($end<=$start||$end-$start>370*86400)throw new FitnessException('Choose a report covering at most one year.');return ['from'=>$first->format('Y-m-d'),'to'=>$last->modify('-1 day')->format('Y-m-d'),'timezone'=>$zone->getName(),'start'=>$start,'end'=>$end,'period'=>$period,'anchor'=>$anchor];
}
function fitness_target_fields(): array {return ['activities'=>'Activities','active_minutes'=>'Active minutes','distance_km'=>'Distance (km)','steps'=>'Session steps'];}
function fitness_target_input(array $in): array {$out=[];foreach(fitness_target_fields()as$k=>$label)$out[$k]=fitness_number($in[$k]??null,match($k){'activities'=>2000,'active_minutes'=>600000,'distance_km'=>100000,default=>100000000},in_array($k,['activities','steps'],true));return $out;}
function fitness_target_key(array $range): string {if(!in_array($range['period'],['week','month','year'],true))throw new FitnessException('Targets apply to a calendar week, month or year.');return $range['period'].':'.$range['from'].':'.$range['timezone'];}
function fitness_progress(array $report,array $targets,bool $complete): array {
 $clean=$report['count']-$report['overlap'];$values=['activities'=>$clean,'active_minutes'=>$report['totals']['seconds']===null?null:$report['totals']['seconds']/60,'distance_km'=>$report['totals']['distance_m']===null?null:$report['totals']['distance_m']/1000,'steps'=>$report['totals']['steps']];$metrics=['active_minutes'=>'seconds','distance_km'=>'distance_m','steps'=>'steps'];$out=[];
 foreach(fitness_target_fields()as$key=>$label){$all=$complete&&$report['overlap']===0&&($key==='activities'||$report['known'][$metrics[$key]]===$clean);$target=$targets[$key]??null;$out[$key]=['label'=>$label,'value'=>$values[$key],'target'=>$target,'complete'=>$all,'percent'=>$all&&$values[$key]!==null&&$target!==null&&$target>0?100.0*$values[$key]/$target:null];}return $out;
}
function fitness_graph(array $report,string $metric,bool $complete=false): array {
 if(!isset(fitness_target_fields()[$metric]))throw new FitnessException('Choose a graph metric.');$zone=new DateTimeZone($report['range']['timezone']);$monthly=$report['range']['period']==='year';$date=(new DateTimeImmutable('@'.$report['range']['start']))->setTimezone($zone);$buckets=[];
 while($date->getTimestamp()<$report['range']['end']){$key=$date->format($monthly?'Y-m':'Y-m-d');$buckets[$key]=['label'=>$date->format($monthly?'M':'j M'),'value'=>$complete&&$date->getTimestamp()<=time()?0:null,'known'=>0,'count'=>0,'future'=>$date->getTimestamp()>time()];$date=$date->modify($monthly?'+1 month':'+1 day');}
 foreach($report['rows']as$r){$key=(new DateTimeImmutable('@'.$r['start']))->setTimezone($zone)->format($monthly?'Y-m':'Y-m-d');if(!isset($buckets[$key]))continue;if($r['overlap']){$buckets[$key]['overlap']=true;continue;}$buckets[$key]['count']++;$value=match($metric){'activities'=>1,'active_minutes'=>$r['seconds']===null?null:$r['seconds']/60,'distance_km'=>$r['distance_m']===null?null:$r['distance_m']/1000,'steps'=>$r['steps']};if($value!==null){$buckets[$key]['value']=($buckets[$key]['value']??0)+$value;$buckets[$key]['known']++;}}
 foreach($buckets as&$b)if($b['known']<$b['count']||!empty($b['overlap']))$b['value']=null;unset($b);return $buckets;
}

function fitness_report(array $rows,array $range,string $source): array {
 fitness_provider($source);$rows=array_values(array_filter(fitness_unique($rows),static fn($r)=>$r['source']===$source&&$r['start']>=$range['start']&&$r['start']<$range['end']));usort($rows,static fn($a,$b)=>$a['start']<=>$b['start']);$overlap=[];
 // Ambiguous overlapping recordings remain visible but do not inflate summary totals.
 for($i=0;$i<count($rows);$i++)for($j=$i+1;$j<count($rows)&&$rows[$j]['start']<$rows[$i]['end'];$j++){if(min($rows[$i]['end'],$rows[$j]['end'])-max($rows[$i]['start'],$rows[$j]['start'])>0){$overlap[$i]=true;$overlap[$j]=true;}}
 $totals=['seconds'=>null,'distance_m'=>null,'steps'=>null,'calories_kcal'=>null];$known=array_fill_keys(array_keys($totals),0);$days=[];
 foreach($rows as$i=>&$r){$r['overlap']=isset($overlap[$i]);$r['pace']=!$r['overlap']&&$r['seconds']!==null&&$r['distance_m']!==null&&$r['distance_m']>0&&$r['seconds']>0?$r['seconds']/($r['distance_m']/1000):null;if($r['overlap'])continue;$day=(new DateTimeImmutable('@'.$r['start']))->setTimezone(new DateTimeZone($range['timezone']))->format('Y-m-d');$days[$day]=($days[$day]??0)+1;foreach($totals as$k=>$v)if($r[$k]!==null){$totals[$k]=($totals[$k]??0)+$r[$k];$known[$k]++;}}unset($r);
 return ['rows'=>$rows,'totals'=>$totals,'known'=>$known,'days'=>$days,'overlap'=>count($overlap),'count'=>count($rows),'source'=>$source,'range'=>$range];
}
function fitness_strava_row(array $r): array {
 if(!is_int($r['id']??null)||!is_string($r['start_date']??null))throw new FitnessException('Strava returned an invalid activity.');$start=fitness_time($r['start_date']);$elapsed=fitness_number($r['elapsed_time']??null,604800,true);if($elapsed===null||$elapsed<1)throw new FitnessException('Strava activity duration is unavailable.');
 return fitness_row(['id'=>(string)$r['id'],'title'=>$r['name']??'Strava activity','type'=>$r['sport_type']??$r['type']??'Other','start_time'=>$r['start_date'],'end_time'=>gmdate('Y-m-d\TH:i:s\Z',$start+(int)$elapsed),'duration_seconds'=>$r['moving_time']??null,'distance_m'=>$r['distance']??null,'origin'=>'Strava'],'strava');
}
function fitness_google_row(array $r): array {
 $x=$r['exercise']??null;if(!is_array($x)||!is_string($r['name']??null)||!preg_match('~^users/[A-Za-z0-9_-]+/dataTypes/exercise/dataPoints/[A-Za-z0-9_-]{1,200}$~D',$r['name']))throw new FitnessException('Google Health returned an invalid exercise.');$duration=$x['activeDuration']??null;if($duration!==null){if(!is_string($duration)||!preg_match('/^([0-9]+(?:\.[0-9]+)?)s$/D',$duration,$m))throw new FitnessException('Unknown Google Health duration format.');$duration=$m[1];}$metrics=$x['metricsSummary']??[];
 $distance=fitness_number($metrics['distanceMillimeters']??null,2000000000);
 return fitness_row(['id'=>$r['name'],'title'=>$x['displayName']??'Google Health activity','type'=>$x['exerciseType']??'Other','start_time'=>$x['interval']['startTime']??null,'end_time'=>$x['interval']['endTime']??null,'duration_seconds'=>$duration,'distance_m'=>$distance===null?null:$distance/1000,'steps'=>$metrics['steps']??null,'calories_kcal'=>$metrics['caloriesKcal']??null,'origin'=>$r['dataSource']['application']['packageName']??'Google Health'],'google_health');
}
function fitness_csv_cell(mixed $value): string {$s=(string)($value??'');return preg_match('/^[\s]*[=+\-@]|^[\t\r\n]/u',$s)?"'".$s:$s;}
function fitness_export(array $report): string {$f=fopen('php://temp','w+');fputcsv($f,['source','origin','id','title','type','start_utc','end_utc','active_seconds','distance_m','session_steps','calories_kcal','overlap_excluded'],',','"','');foreach($report['rows']as$r)fputcsv($f,array_map('fitness_csv_cell',[$r['source'],$r['origin'],$r['id'],$r['title'],$r['type'],gmdate('c',$r['start']),gmdate('c',$r['end']),$r['seconds'],$r['distance_m'],$r['steps'],$r['calories_kcal'],$r['overlap']?'yes':'no']),',','"','');rewind($f);$s=stream_get_contents($f);fclose($f);return $s;}

function fitness_pace_label(float $pace): string {$seconds=(int)round($pace);return intdiv($seconds,60).':'.str_pad((string)($seconds%60),2,'0',STR_PAD_LEFT);}
